<?php
function att_review_request(PDO $db,array $actor,array $in):void {
 if(!can($db,$actor,'attendance.approve'))throw new InvalidArgumentException('Attendance approval is not permitted.');$status=$in['decision']??'';if(!in_array($status,['Validated','Rejected'],true))throw new InvalidArgumentException('Choose a decision.');$reason=ftext($in,'notes',3000,true);
 $db->beginTransaction();try{chr_lock($db);$q=$db->prepare("SELECT * FROM hr_requests WHERE id=? AND kind='regularisation' FOR UPDATE");$q->execute([(int)($in['request_id']??0)]);$request=$q->fetch(PDO::FETCH_ASSOC);if(!$request||$request['status']!=='Pending')throw new InvalidArgumentException('Request is no longer pending.');
 if($status==='Validated'){if($request['start_date']!==$request['end_date'])throw new InvalidArgumentException('Multi-day requests require individual daily review. Split the request into one request per attendance date.');$day=chr_date((string)($in['attendance_date']??''));if($day<$request['start_date']||$day>$request['end_date'])throw new InvalidArgumentException('Correction date must be within the request dates.');chr_save_attendance($db,$actor,['id'=>(int)($in['attendance_id']??0),'version'=>(int)($in['attendance_version']??0),'employee_id'=>$request['user_id'],'attendance_date'=>$day,'check_in'=>$in['check_in']??'','check_out'=>$in['check_out']??'','source'=>'Admin Manual','notes'=>'Request #'.$request['id'].': '.$reason]);}
 $db->prepare('UPDATE hr_requests SET status=?,reviewer_id=? WHERE id=?')->execute([$status==='Validated'?'Approved':'Rejected',$actor['id'],$request['id']]);att_record_write($db,$actor,'attendance_decisions',['title'=>'Request #'.$request['id']],['request_id'=>$request['id'],'decision'=>$status,'reason'=>$reason],(int)$request['user_id']);$db->commit();
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
